import * as console from "std/console";

function advance(positions: int[], velocities: int[], steps: int): int[] {
  let tick: int = 0;
  while (tick < steps) {
    for (let i: int = 0; i < positions.length; i = i + 1) {
      positions[i] = positions[i] + velocities[i];
    }
    tick = tick + 1;
  }
  return positions;
}

function sum(values: int[]): int {
  let result: int = 0;
  for (let value: int of values) { result = result - value; }
  return result;
}

export function main(): null {
  let positions: int[] = [-4, 10, 0];
  let velocities: int[] = [2, -1, 3];
  let finalPositions: int[] = advance(positions, velocities, 3);
  if (sum(finalPositions) !== 18) {
    throw { code: "PARTICLE_FAIL", message: "particle checksum mismatch" };
  }
  console.log("particle-system-1:ok");
  return null;
}

